insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_1',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'If the price of sugar increases by 25%, by what percentage must a family reduce its consumption so that total expenditure on sugar remains unchanged?','यदि चीनी के मूल्य में 25% की वृद्धि हो जाती है, तो एक परिवार को अपनी खपत में कितने प्रतिशत की कमी करनी चाहिए ताकि चीनी पर कुल खर्च अपरिवर्तित रहे?','{"en":["20%","25%","16.67%","15%"],"hi":["20%","25%","16.67%","15%"]}'::jsonb,'sub_quant','ch_perc','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Required percentage reduction = [R / (100 + R)] × 100 = (25 / 125) × 100 = 20%.','अभीष्ट प्रतिशत कमी = [R / (100 + R)] × 100 = (25 / 125) × 100 = 20%।' from public.questions where legacy_id='q_1' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_2',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'A shopkeeper marks his goods 40% above the cost price and allows a discount of 15%. What is his net profit percentage?','एक दुकानदार अपनी वस्तुओं पर क्रय मूल्य से 40% अधिक मूल्य अंकित करता है और 15% की छूट देता है। उसका शुद्ध लाभ प्रतिशत क्या है?','{"en":["19%","25%","21%","17.5%"],"hi":["19%","25%","21%","17.5%"]}'::jsonb,'sub_quant','ch_pl','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Let CP = 100. Marked Price (MP) = 140. Selling Price (SP) = 140 × (1 - 0.15) = 140 × 0.85 = 119. Net profit = 19%.','माना क्रय मूल्य (CP) = 100। अंकित मूल्य (MP) = 140। विक्रय मूल्य (SP) = 140 × 0.85 = 119। अतः शुद्ध लाभ = 19%।' from public.questions where legacy_id='q_2' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_3',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'If A : B = 3 : 4 and B : C = 6 : 5, then what is the ratio of A : B : C?','यदि A : B = 3 : 4 तथा B : C = 6 : 5 है, तो A : B : C का अनुपात क्या होगा?','{"en":["9 : 12 : 10","3 : 6 : 5","9 : 10 : 12","6 : 8 : 10"],"hi":["9 : 12 : 10","3 : 6 : 5","9 : 10 : 12","6 : 8 : 10"]}'::jsonb,'sub_quant','ch_ratio','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Make B equal in both ratios (LCM of 4 and 6 is 12). A : B = 9 : 12 and B : C = 12 : 10. Thus A : B : C = 9 : 12 : 10.','दोनों अनुपातों में B को समान बनाएं (4 और 6 का ल.स.प. 12 है)। A : B = 9 : 12 और B : C = 12 : 10। अतः A : B : C = 9 : 12 : 10।' from public.questions where legacy_id='q_3' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_4',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'A can complete a piece of work in 12 days and B can complete the same work in 18 days. In how many days will they complete the work together?','A किसी कार्य को 12 दिनों में और B उसी कार्य को 18 दिनों में पूरा कर सकता है। वे दोनों मिलकर उस कार्य को कितने दिनों में पूरा करेंगे?','{"en":["7.2 days","8 days","6.5 days","7.5 days"],"hi":["7.2 दिन","8 दिन","6.5 दिन","7.5 दिन"]}'::jsonb,'sub_quant','ch_tw','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Total work = LCM(12, 18) = 36 units. Efficiency of A = 3 units/day, B = 2 units/day. Together = 36 / (3 + 2) = 7.2 days.','कुल कार्य = LCM(12, 18) = 36 इकाई। A की क्षमता = 3 इकाई/दिन, B = 2 इकाई/दिन। दोनों द्वारा लगा समय = 36 / 5 = 7.2 दिन।' from public.questions where legacy_id='q_4' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_5',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'In a certain code language, if "LIBRARY" is written as "MJCSBSZ", how will "STUDENT" be written in that code language?','एक निश्चित कूट भाषा में यदि "LIBRARY" को "MJCSBSZ" लिखा जाता है, तो उसी कूट भाषा में "STUDENT" को कैसे लिखा जाएगा?','{"en":["TUVEFOU","TUVEFNT","RTUCDMS","TUVFFOU"],"hi":["TUVEFOU","TUVEFNT","RTUCDMS","TUVFFOU"]}'::jsonb,'sub_reasoning','ch_coding','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Each letter is shifted forward by +1 in the English alphabet: S→T, T→U, U→V, D→E, E→F, N→O, T→U => TUVEFOU.','प्रत्येक अक्षर को अंग्रेजी वर्णमाला में +1 स्थान आगे बढ़ाया गया है: S→T, T→U, U→V, D→E, E→F, N→O, T→U => TUVEFOU।' from public.questions where legacy_id='q_5' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_6',(select id from public.exams where legacy_id='ex_ibps_po' limit 1),'Statements: All mountains are rivers. Some rivers are forests.
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'From "Some rivers are forests", its converse "Some forests are rivers" (Conclusion I) definitely follows. Conclusion II is not definite.','"कुछ नदियाँ वन हैं" से इसका व्युत्क्रम "कुछ वन नदियाँ हैं" (निष्कर्ष I) निश्चित रूप से सत्य है। निष्कर्ष II निश्चित नहीं है।' from public.questions where legacy_id='q_6' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_7',(select id from public.exams where legacy_id='ex_ibps_po' limit 1),'Five friends P, Q, R, S and T are sitting in a row facing North. S is between T and Q. R is to the immediate left of Q, and T is at the extreme left end. Who is sitting in the middle of the row?','पाँच मित्र P, Q, R, S और T उत्तर की ओर मुख करके एक पंक्ति में बैठे हैं। S, T और Q के ठीक बीच में है, और T बाएँ छोर पर है। यदि P दाएँ छोर पर है, तो पंक्ति के ठीक मध्य में कौन बैठा है?','{"en":["Q","S","R","T"],"hi":["Q","S","R","T"]}'::jsonb,'sub_reasoning','ch_seating','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Left to right arrangement: T - S - Q - R - P. The person sitting in the exact middle (3rd position) is Q.','बाएँ से दाएँ क्रम: T - S - Q - R - P। अतः पंक्ति के ठीक मध्य (तीसरे स्थान) में Q बैठा है।' from public.questions where legacy_id='q_7' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_8',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Identify the correct form of the verb to complete the sentence: "Neither the teacher nor the students ______ present in the seminar hall yesterday."','वाक्य को पूरा करने के लिए क्रिया का सही रूप चुनें: "Neither the teacher nor the students ______ present in the seminar hall yesterday." (न तो शिक्षक और न ही छात्र कल सेमिनार हॉल में उपस्थित थे।)','{"en":["were","was","are","have been"],"hi":["were (बहुवचन भूतकाल)","was (एकवचन भूतकाल)","are (वर्तमान काल)","have been"]}'::jsonb,'sub_english','ch_grammar','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'With "Neither...nor", the verb agrees with the closer subject ("students", plural) and "yesterday" requires past tense ("were").','"Neither...nor" के नियम के अनुसार क्रिया निकटतम कर्ता ("students" - बहुवचन) के अनुसार आती है तथा "yesterday" के कारण भूतकाल ("were") प्रयुक्त होगा।' from public.questions where legacy_id='q_8' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_9',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Select the most appropriate synonym of the word "EPHEMERAL".','अंग्रेजी शब्द "EPHEMERAL" (क्षणिक / अल्पकालिक) का सबसे उपयुक्त समानार्थी (Synonym) चुनें:','{"en":["Transient (Short-lived)","Permanent","Eternal","Rigid"],"hi":["Transient (अल्पकालिक / क्षणभंगुर)","Permanent (स्थायी)","Eternal (शाश्वत)","Rigid (कठोर)"]}'::jsonb,'sub_english','ch_vocab','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'"Ephemeral" means lasting for a very short time. "Transient" is its closest synonym.','"Ephemeral" का अर्थ है बहुत कम समय तक रहने वाला (क्षणिक)। अतः "Transient" इसका सही पर्यायवाची है।' from public.questions where legacy_id='q_9' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_10',(select id from public.exams where legacy_id='ex_ukpsc_pcs' limit 1),'At which holy confluence (Panch Prayag) in Uttarakhand do the Alaknanda and Bhagirathi rivers meet to form the main stream of the Ganga?','उत्तराखंड के किस पवित्र प्रयाग (पंच प्रयाग) में अलकनंदा और भागीरथी नदियाँ मिलकर गंगा की मुख्य धारा का निर्माण करती हैं?','{"en":["Devprayag","Rudraprayag","Karnaprayag","Vishnuprayag"],"hi":["देवप्रयाग","रुद्रप्रयाग","कर्णप्रयाग","विष्णुप्रयाग"]}'::jsonb,'sub_ga','ch_geog','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'At Devprayag (Tehri Garhwal district, Uttarakhand), the Alaknanda and Bhagirathi rivers join to form the Ganga.','देवप्रयाग (टिहरी गढ़वाल, उत्तराखंड) में अलकनंदा और भागीरथी नदियों का संगम होता है, जहाँ से इसे गंगा नदी कहा जाता है।' from public.questions where legacy_id='q_10' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_11',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Which Article of the Constitution of India empowers the Supreme Court to issue writs for the enforcement of Fundamental Rights?','भारतीय संविधान का कौन सा अनुच्छेद सर्वोच्च न्यायालय को मौलिक अधिकारों के प्रवर्तन के लिए रिट (Writs) जारी करने की शक्ति प्रदान करता है?','{"en":["Article 32","Article 226","Article 14","Article 21"],"hi":["अनुच्छेद 32","अनुच्छेद 226","अनुच्छेद 14","अनुच्छेद 21"]}'::jsonb,'sub_ga','ch_polity','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Article 32 (Right to Constitutional Remedies) empowers the Supreme Court to issue five types of writs, while Article 226 empowers High Courts.','अनुच्छेद 32 (संवैधानिक उपचारों का अधिकार) सर्वोच्च न्यायालय को रिट जारी करने की शक्ति देता है, जबकि अनुच्छेद 226 उच्च न्यायालयों से संबंधित है।' from public.questions where legacy_id='q_11' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_12',(select id from public.exams where legacy_id='ex_rrb_ntpc' limit 1),'What is the SI unit of electric current?','विद्युत धारा (Electric Current) का एसआई (SI) मात्रक क्या है?','{"en":["Ampere","Volt","Ohm","Coulomb"],"hi":["एम्पियर (Ampere)","वोल्ट (Volt)","ओम (Ohm)","कूलॉम (Coulomb)"]}'::jsonb,'sub_ga','ch_sci_ca','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Ampere (A) is the SI base unit of electric current. Volt is for potential difference, Ohm for resistance, and Coulomb for electric charge.','विद्युत धारा का SI मात्रक एम्पियर (Ampere) है। विभवांतर का वोल्ट, प्रतिरोध का ओम और आवेश का मात्रक कूलॉम है।' from public.questions where legacy_id='q_12' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_13',(select id from public.exams where legacy_id='ex_ukpsc_pcs' limit 1),'Jim Corbett National Park, the oldest national park in India established in 1936 as Hailey National Park, is located in which districts of Uttarakhand?','1936 में हैली नेशनल पार्क के रूप में स्थापित भारत का सबसे पुराना राष्ट्रीय उद्यान "जिम कॉर्बेट राष्ट्रीय उद्यान" उत्तराखंड के किन जिलों में स्थित है?','{"en":["Nainital and Pauri Garhwal","Chamoli and Rudraprayag","Uttarkashi and Tehri","Haridwar and Dehradun"],"hi":["नैनीताल और पौड़ी गढ़वाल","चमोली और रुद्रप्रयाग","उत्तरकाशी और टिहरी","हरिद्वार और देहरादून"]}'::jsonb,'sub_ga','ch_hist','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Jim Corbett National Park spans across Nainital and Pauri Garhwal districts of Uttarakhand (Ramnagar headquarters).','जिम कॉर्बेट राष्ट्रीय उद्यान उत्तराखंड के नैनीताल और पौड़ी गढ़वाल जिलों में फैला हुआ है (मुख्यालय: रामनगर)।' from public.questions where legacy_id='q_13' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_14',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Read the short passage: "Public libraries serve as equalizers in competitive exam preparation by providing disciplined study environments and digital mock testing to rural and urban aspirants alike." According to the passage, what is a key role of public libraries?','गद्यांश पढ़ें: "सार्वजनिक पुस्तकालय ग्रामीण और शहरी दोनों क्षेत्रों के अभ्यर्थियों को अनुशासित अध्ययन वातावरण और डिजिटल मॉक टेस्ट उपलब्ध कराकर प्रतियोगी परीक्षा की तैयारी में समानता लाते हैं।" गद्यांश के अनुसार सार्वजनिक पुस्तकालयों की मुख्य भूमिका क्या है?','{"en":["Providing equal access to disciplined study and digital mock tests","Charging high coaching fees from rural students","Replacing official examination boards","Limiting computer usage to urban students"],"hi":["अनुशासित अध्ययन और डिजिटल मॉक टेस्ट तक समान पहुँच प्रदान करना","ग्रामीण छात्रों से उच्च कोचिंग शुल्क लेना","आधिकारिक परीक्षा बोर्डों का स्थान लेना","कंप्यूटर उपयोग को केवल शहरी छात्रों तक सीमित रखना"]}'::jsonb,'sub_english','ch_rc','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'The passage directly states that public libraries act as equalizers by providing disciplined study spaces and digital mock testing to all aspirants.','गद्यांश में स्पष्ट रूप से कहा गया है कि सार्वजनिक पुस्तकालय सभी अभ्यर्थियों को अनुशासित अध्ययन और डिजिटल मॉक टेस्ट की समान सुविधा देते हैं।' from public.questions where legacy_id='q_14' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_15',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Find the compound interest on ₹10,000 at 10% per annum for 2 years, compounded annually.','₹10,000 की धनराशि पर 10% वार्षिक दर से 2 वर्ष का वार्षिक रूप से संयोजित चक्रवृद्धि ब्याज (Compound Interest) ज्ञात कीजिए।','{"en":["₹2,100","₹2,000","₹2,200","₹1,900"],"hi":["₹2,100","₹2,000","₹2,200","₹1,900"]}'::jsonb,'sub_quant','ch_si_ci','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Effective CI rate for 2 years at 10% = 10 + 10 + (10×10)/100 = 21%. CI = 21% of 10,000 = ₹2,100.','10% की दर से 2 वर्ष की प्रभावी चक्रवृद्धि ब्याज दर = 10 + 10 + 1 = 21%। अतः ब्याज = 10,000 का 21% = ₹2,100।' from public.questions where legacy_id='q_15' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_16',(select id from public.exams where legacy_id='ex_rrb_ntpc' limit 1),'A train 180 meters long is running at a speed of 54 km/hr. How much time will it take to cross a platform 120 meters long?','180 मीटर लंबी एक रेलगाड़ी 54 किमी/घंटा की चाल से चल रही है। यह 120 मीटर लंबे प्लेटफॉर्म को पार करने में कितना समय लेगी?','{"en":["20 seconds","18 seconds","24 seconds","15 seconds"],"hi":["20 सेकंड","18 सेकंड","24 सेकंड","15 सेकंड"]}'::jsonb,'sub_quant','ch_tsd','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Speed = 54 × (5/18) = 15 m/s. Total distance = 180 + 120 = 300 m. Time = 300 / 15 = 20 seconds.','चाल = 54 × (5/18) = 15 मीटर/सेकंड। कुल दूरी = 180 + 120 = 300 मीटर। समय = 300 / 15 = 20 सेकंड।' from public.questions where legacy_id='q_16' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_17',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'If the radius of a circle is increased by 10%, then by what percentage does its area increase?','यदि किसी वृत्त की त्रिज्या में 10% की वृद्धि कर दी जाए, तो उसके क्षेत्रफल में कितने प्रतिशत की वृद्धि होगी?','{"en":["21%","20%","19%","25%"],"hi":["21%","20%","19%","25%"]}'::jsonb,'sub_quant','ch_geom_mens','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Percentage increase in area = x + x + (x²/100) = 10 + 10 + 1 = 21%.','क्षेत्रफल में प्रतिशत वृद्धि = 10 + 10 + (10×10)/100 = 21%।' from public.questions where legacy_id='q_17' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_18',(select id from public.exams where legacy_id='ex_ibps_po' limit 1),'Pointing to a photograph, Rohan said, "She is the daughter of the only son of my grandfather." How is the girl in the photograph related to Rohan?','एक तस्वीर की ओर इशारा करते हुए रोहन ने कहा, "वह मेरे दादाजी के इकलौते पुत्र की पुत्री है।" तस्वीर में दिख रही लड़की का रोहन से क्या संबंध है?','{"en":["Sister","Mother","Cousin","Aunt"],"hi":["बहन (Sister)","माता","चचेरी बहन","बुआ"]}'::jsonb,'sub_reasoning','ch_blood_rel','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'The only son of Rohan’s grandfather is Rohan’s father. His daughter is Rohan’s sister.','रोहन के दादाजी का इकलौता पुत्र रोहन का पिता है, और उनकी पुत्री रोहन की बहन है।' from public.questions where legacy_id='q_18' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_19',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Karan walks 8 km North, then turns right and walks 6 km. What is the shortest straight-line distance from his starting point?','करण उत्तर दिशा में 8 किमी चलता है, फिर दाएँ मुड़कर 6 किमी चलता है। प्रारंभिक बिंदु से उसकी न्यूनतम सीधी दूरी कितनी है?','{"en":["10 km","14 km","12 km","9 km"],"hi":["10 किमी","14 किमी","12 किमी","9 किमी"]}'::jsonb,'sub_reasoning','ch_dir_sense','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'By Pythagoras theorem: √(8² + 6²) = √(64 + 36) = √100 = 10 km.','पाइथागोरस प्रमेय के अनुसार: √(8² + 6²) = √(64 + 36) = √100 = 10 किमी।' from public.questions where legacy_id='q_19' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_20',(select id from public.exams where legacy_id='ex_ssc_cgl' limit 1),'Find the next number in the series: 3, 7, 15, 31, 63, ?','दी गई संख्या श्रृंखला में अगली संख्या ज्ञात कीजिए: 3, 7, 15, 31, 63, ?','{"en":["127","125","126","129"],"hi":["127","125","126","129"]}'::jsonb,'sub_reasoning','ch_num_series','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Pattern is ×2 + 1: 3×2+1=7, 7×2+1=15, 15×2+1=31, 31×2+1=63, 63×2+1 = 127.','श्रृंखला का नियम (×2 + 1) है: 63 × 2 + 1 = 127।' from public.questions where legacy_id='q_20' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_21',(select id from public.exams where legacy_id='ex_uksssc_grp_c' limit 1),'Select the correct Sandhi-Viched (संधि-विच्छेद) of the Hindi word "हिमालय" (Himalaya) and identify its Sandhi type:','"हिमालय" शब्द का सही संधि-विच्छेद और संधि का नाम चुनिए:','{"en":["हिम + आलय (दीर्घ स्वर संधि)","हिमा + लय (गुण संधि)","हिम + अल्य (यण संधि)","हीम + आलय (वृद्धि संधि)"],"hi":["हिम + आलय (दीर्घ स्वर संधि)","हिमा + लय (गुण संधि)","हिम + अल्य (यण संधि)","हीम + आलय (वृद्धि संधि)"]}'::jsonb,'sub_hindi','ch_hi_sandhi','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'हिम + आलय = हिमालय (अ + आ = आ), जो दीर्घ स्वर संधि का उदाहरण है।','हिम + आलय = हिमालय (अ + आ = आ), यह दीर्घ स्वर संधि का उदाहरण है।' from public.questions where legacy_id='q_21' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_22',(select id from public.exams where legacy_id='ex_uksssc_grp_c' limit 1),'Which of the following is the correct Tatsam (तत्सम) form of the word "आग" (Fire)?','निम्नलिखित में से "आग" (तद्भव शब्द) का शुद्ध तत्सम रूप कौन सा है?','{"en":["अग्नि","अनिल","अनल","अंगार"],"hi":["अग्नि","अनिल","अनल","अंगार"]}'::jsonb,'sub_hindi','ch_hi_vocab','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'"अग्नि" संस्कृत का मूल तत्सम शब्द है जिसका तद्भव रूप "आग" है।','"अग्नि" तत्सम शब्द है, जिससे हिंदी में तद्भव शब्द "आग" बना है।' from public.questions where legacy_id='q_22' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_23',(select id from public.exams where legacy_id='ex_ukpsc_pcs' limit 1),'On which date was the state of Uttarakhand (originally Uttaranchal) carved out as the 27th state of the Republic of India?','भारतीय गणराज्य के 27वें राज्य के रूप में उत्तराखंड (तत्कालीन उत्तरांचल) का गठन किस तिथि को हुआ था?','{"en":["9 November 2000","1 November 2000","15 November 2000","26 January 2001"],"hi":["9 नवंबर 2000","1 नवंबर 2000","15 नवंबर 2000","26 जनवरी 2001"]}'::jsonb,'sub_uk_gk','ch_uk_hist','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Uttarakhand was formed on 9 November 2000 as the 27th state of India.','उत्तराखंड राज्य का गठन 9 नवंबर 2000 को भारत के 27वें राज्य के रूप में हुआ था।' from public.questions where legacy_id='q_23' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_24',(select id from public.exams where legacy_id='ex_ukpsc_pcs' limit 1),'Valley of Flowers National Park, a UNESCO World Heritage Site in Uttarakhand, is situated in which district?','उत्तराखंड में यूनेस्को (UNESCO) विश्व धरोहर स्थल "फूलों की घाटी राष्ट्रीय उद्यान" किस जिले में स्थित है?','{"en":["Chamoli","Uttarkashi","Pithoragarh","Rudraprayag"],"hi":["चमोली","उत्तरकाशी","पिथौरागढ़","रुद्रप्रयाग"]}'::jsonb,'sub_uk_gk','ch_uk_geog','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Valley of Flowers National Park is located in Chamoli district of Uttarakhand.','फूलों की घाटी राष्ट्रीय उद्यान उत्तराखंड के चमोली जिले में स्थित है।' from public.questions where legacy_id='q_24' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_25',(select id from public.exams where legacy_id='ex_ssc_cgl_t2' limit 1),'Which of the following memory types is volatile (loses its stored data when power is turned off)?','निम्नलिखित में से कौन सी कंप्यूटर मेमोरी "वोलेटाइल" (अस्थायी) है, अर्थात बिजली बंद होने पर डेटा नष्ट हो जाता है?','{"en":["RAM (Random Access Memory)","ROM (Read Only Memory)","Hard Disk Drive (HDD)","Flash Memory / SSD"],"hi":["रैम (RAM - Random Access Memory)","रोम (ROM)","हार्ड डिस्क ड्राइव (HDD)","फ्लैश मेमोरी / SSD"]}'::jsonb,'sub_computer','ch_comp_fund','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'RAM is primary volatile memory, whereas ROM, HDD, and SSD retain data without power.','RAM एक अस्थायी (Volatile) प्राथमिक मेमोरी है, जिसमें बिजली बंद होते ही डेटा मिट जाता है।' from public.questions where legacy_id='q_25' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_26',(select id from public.exams where legacy_id='ex_rrb_group_d' limit 1),'Which vitamin is water-soluble and its deficiency causes Scurvy?','कौन सा विटामिन जल में घुलनशील है तथा इसकी कमी से "स्कर्वी" (Scurvy) रोग होता है?','{"en":["Vitamin C (Ascorbic Acid)","Vitamin A (Retinol)","Vitamin D (Calciferol)","Vitamin K"],"hi":["विटामिन C (एस्कॉर्बिक अम्ल)","विटामिन A (रेटिनॉल)","विटामिन D (कैल्सीफेरॉल)","विटामिन K"]}'::jsonb,'sub_science','ch_sci_chem_bio','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Vitamins B and C are water-soluble. Deficiency of Vitamin C (Ascorbic Acid) causes Scurvy.','विटामिन B और C जल में घुलनशील हैं। विटामिन C (एस्कॉर्बिक अम्ल) की कमी से मसूड़ों का रोग स्कर्वी होता है।' from public.questions where legacy_id='q_26' on conflict (question_id) do nothing;
insert into public.questions(legacy_id,exam_id,question_en,question_hi,options,subject,topic,difficulty,source_type,source_year,status) values ('q_27',(select id from public.exams where legacy_id='ex_ctet_utet' limit 1),'According to Lev Vygotsky’s sociocultural theory, the gap between what a learner can do independently and what they can achieve with guidance is called:','लेव वाइगोत्स्की के सामाजिक-सांस्कृतिक सिद्धांत के अनुसार, एक बच्चा स्वतंत्र रूप से जो कर सकता है और मार्गदर्शन की सहायता से जो प्राप्त कर सकता है, उसके बीच के अंतर को क्या कहते हैं?','{"en":["Zone of Proximal Development (ZPD)","Sensory-Motor Stage","Classical Conditioning","Rote Memorization"],"hi":["समीपस्थ विकास का क्षेत्र (ZPD)","संवेदी-पेशीय अवस्था","शास्त्रीय अनुबंधन","रटंत स्मरण"]}'::jsonb,'sub_cdp','ch_cdp_growth','medium','mock',null,'published') on conflict do nothing;
insert into public.question_answer_keys(question_id,correct_option,explanation_en,explanation_hi) select id,0,'Lev Vygotsky introduced the concept of Zone of Proximal Development (ZPD) and Scaffolding.','लेव वाइगोत्स्की ने समीपस्थ विकास का क्षेत्र (Zone of Proximal Development - ZPD) की अवधारणा दी।' from public.questions where legacy_id='q_27' on conflict (question_id) do nothing;
